digraph DialogueGraph {
  rankdir=LR;
  node [shape=box, style=rounded];

  0 [label="Narrator\nThe tavern door creaks open. Smoke and laughter fill the air.", fillcolor=lightgray, style=filled];
  1 [label="Narrator\nThree figures catch your eye: a hooded stranger, a boisterous merchant, and the barkeep.", fillcolor=lightgray, style=filled];
  2 [label="Narrator\nYou notice the stranger slipping a note to the barkeep. The merchant counts gold nervously.", fillcolor=lightgray, style=filled];
  3 [label="Stranger\nYou dare?!", fillcolor=lightgray, style=filled];
  4 [label="Narrator\n50 gold pieces heavier, you slip away. The merchant hasn't noticed... yet.", fillcolor=lightgray, style=filled];
  5 [label="Merchant\nWatch it, friend!", fillcolor=lightgray, style=filled];
  6 [label="Merchant\nHmph. Buy me a drink and we're even.", fillcolor=lightgray, style=filled];
  7 [label="Merchant\nWhy you little—!", fillcolor=lightgray, style=filled];
  8 [label="Narrator\nBut where to spend your ill-gotten gains?", fillcolor=lightgray, style=filled];
  9 [label="Stranger\nYou have the look of someone seeking something.", fillcolor=lightgray, style=filled];
  10 [label="Stranger\nThe Crimson Blade? Many seek it. Few survive.", fillcolor=lightgray, style=filled];
  11 [label="Stranger\nThen you'll need a map. I have one... for a price.", fillcolor=lightgray, style=filled];
  12 [label="Stranger\n100 gold, or a favor to be named later.", fillcolor=lightgray, style=filled];
  13 [label="Stranger\nWise choice. No strings attached.", fillcolor=lightgray, style=filled];
  14 [label="Stranger\nRemember, I always collect.", fillcolor=lightgray, style=filled];
  15 [label="Stranger\nYou drive a hard bargain. Agreed.", fillcolor=lightgray, style=filled];
  16 [label="Stranger\nYour silver tongue amuses me. 75 gold, final offer.", fillcolor=lightgray, style=filled];
  17 [label="Stranger\nYour loss. The Blade waits for no one.", fillcolor=lightgray, style=filled];
  18 [label="Stranger\nThe mountain claims them. Traps, guardians, madness itself.", fillcolor=lightgray, style=filled];
  19 [label="Stranger\nStone sentinels that never sleep. Best approached with stealth... or great power.", fillcolor=lightgray, style=filled];
  20 [label="Stranger\nA mage, then. You may yet survive. Take this.", fillcolor=lightgray, style=filled];
  21 [label="Stranger\nA rogue's path. Dangerous but possible.", fillcolor=lightgray, style=filled];
  22 [label="Stranger\nThe mountain whispers. Those who listen too long... never leave.", fillcolor=lightgray, style=filled];
  23 [label="Stranger\nConfidence or foolishness? We shall see.", fillcolor=lightgray, style=filled];
  24 [label="Stranger\nHa! I like you. Maybe you'll be the one.", fillcolor=lightgray, style=filled];
  25 [label="Stranger\nThe Crimson Blade awaits at the peak of Mount Sorrow. Go.", fillcolor=lightgray, style=filled];
  26 [label="Stranger\nRemember our deal. I will find you when the time is right.", fillcolor=lightgray, style=filled];
  27 [label="Stranger\nA fair trade. Now go, before the trail grows cold.", fillcolor=lightgray, style=filled];
  28 [label="Narrator\nYou pocket the map. Your journey begins at dawn.", fillcolor=lightgray, style=filled];
  29 [label="Narrator\nThe map feels heavy in your hands. What have you agreed to?", fillcolor=lightgray, style=filled];
  30 [label="Narrator\nYou gather supplies and rest. Dawn breaks cold and clear.", fillcolor=lightgray, style=filled];
  31 [label="Narrator\nWho might know more about Mount Sorrow?", fillcolor=lightgray, style=filled];
  32 [label="Barkeep\nMount Sorrow? My grandfather went there once. Came back without his voice. Said he traded it for wisdom.", fillcolor=lightgray, style=filled];
  33 [label="Barkeep\nHe wrote it down before he died. Want to see?", fillcolor=lightgray, style=filled];
  34 [label="Barkeep\nIt says: \"The silence speaks truth. Listen with your heart, not your ears.\"", fillcolor=lightgray, style=filled];
  35 [label="Narrator\nCryptic, but perhaps useful. You commit it to memory.", fillcolor=lightgray, style=filled];
  36 [label="Barkeep\nSmart. 20 gold for the journal.", fillcolor=lightgray, style=filled];
  37 [label="Barkeep\nTake it or leave it.", fillcolor=lightblue, style=filled];
  38 [label="Barkeep\nYou're kind. Take the journal. He would have wanted it to help someone.", fillcolor=lightgray, style=filled];
  39 [label="Merchant\nMount Sorrow? I've sold equipment to three expeditions. None returned for refunds.", fillcolor=lightgray, style=filled];
  40 [label="Merchant\nClimbing tools, wards against magic, and plenty of rope. Most came back for more rope.", fillcolor=lightgray, style=filled];
  41 [label="Narrator\nPerhaps you should stock up.", fillcolor=lightgray, style=filled];
  42 [label="Merchant\nHey, a sale's a sale. Not my fault if they don't come back.", fillcolor=lightgray, style=filled];
  43 [label="Merchant\n...I light a candle for each of them. Not that it helps.", fillcolor=lightgray, style=filled];
  44 [label="Merchant\nLook, take this charm. It's supposed to protect against curses. For free. Consider it penance.", fillcolor=lightgray, style=filled];
  45 [label="Narrator\nYou receive a strange amulet. It pulses faintly with warmth.", fillcolor=lightgray, style=filled];

