python3 << 'EOF'
import json

with open('/app/dialogue.json', 'r') as f:
    graph = json.load(f)

nodes = graph['nodes']
edges = graph['edges']

# Build adjacency list
adj_list = {}
for edge in edges:
    from_id = edge['from']
    to_id = edge['to']

    if from_id not in adj_list:
        adj_list[from_id] = []

    # Only follow edges to node IDs (not "End")
    if isinstance(to_id, int):
        adj_list[from_id].append(to_id)

# BFS from start node
start_node_id = nodes[0]['id']
reachable = set()
queue = [start_node_id]

while queue:
    current = queue.pop(0)
    if current in reachable:
        continue
    reachable.add(current)

    if current in adj_list:
        for neighbor in adj_list[current]:
            if neighbor not in reachable:
                queue.append(neighbor)

# Check reachability
node_ids = {node['id'] for node in nodes}
unreachable = node_ids - reachable

print(f"Total nodes: {len(nodes)}")
print(f"Reachable nodes: {len(reachable)}")
print(f"Unreachable nodes: {len(unreachable)}")

if unreachable:
    print(f"\nFirst 20 unreachable nodes: {sorted(list(unreachable))[:20]}")

    # Check if unreachable nodes have any incoming edges
    incoming_edges = {}
    for edge in edges:
        if isinstance(edge['to'], int):
            if edge['to'] not in incoming_edges:
                incoming_edges[edge['to']] = []
            incoming_edges[edge['to']].append(edge['from'])

    print(f"\nChecking if unreachable nodes have incoming edges...")
    for node_id in sorted(list(unreachable))[:10]:
        incoming = incoming_edges.get(node_id, [])
        print(f"  Node {node_id}: {len(incoming)} incoming edges from {incoming[:5]}")
else:
    print("\n✓ All nodes are reachable!")
EOF

